    function loadQuestion() {
        const qData = questions[currentQuestionIndex];

        // Atualiza UI
        document.getElementById('current-q-num').innerText = currentQuestionIndex + 1;
        document.getElementById('question-text').innerText = qData.q;

        // Limpa opções anteriores
        const list = document.getElementById('options-list');
        list.innerHTML = '';

        // Oculta botão próximo
        document.getElementById('next-btn').style.display = 'none';

        // Cria novas opções
        qData.options.forEach((opt, index) => {
            const li = document.createElement('li');
            li.className = 'option-item';
            li.onclick = () => selectOption(index, li);

            const label = document.createElement('span');
            label.className = 'option-label';
            label.innerText = `[${String.fromCharCode(65 + index)}]`;

            const text = document.createElement('span');
            text.innerText = ' ' + opt;

            li.appendChild(label);
            li.appendChild(text);
            list.appendChild(li);
        });

        // Atualiza barra de progresso
        const progressPercent = ((currentQuestionIndex) / questions.length) * 100;
        document.getElementById('progress-bar').style.width = `${progressPercent}%`;
    }

    function selectOption(optionIndex, element) {
        // Desabilita cliques subsequentes nesta questão
        const items = document.querySelectorAll('.option-item');
        items.forEach(item => item.classList.add('disabled'));

        // Salva resposta temporariamente
        userAnswers.push({
            questionIndex: currentQuestionIndex,
            selectedOption: optionIndex,
            questionText: questions[currentQuestionIndex].q
        });

        // Marca visualmente
        if (optionIndex === questions[currentQuestionIndex].correct) {
            element.classList.add('correct');
            score++;
        } else {
            element.classList.add('wrong');
            // Mostra a correta também
            items[questions[currentQuestionIndex].correct].classList.add('correct');
        }

        document.getElementById('next-btn').style.display = 'block';
    }

    function nextQuestion() {
        currentQuestionIndex++;

        if (currentQuestionIndex < questions.length) {
            loadQuestion();
        } else {
            showResults();
        }
    }

    function showResults() {
        document.getElementById('quiz-screen').classList.remove('active');
        document.getElementById('result-screen').classList.add('active');

        // Exibe nota
        document.getElementById('final-score').innerText = score;

        let msg = "";
        if(score === 20) msg = "Excelente! Você domina a legislação.";
        else if(score >= 15) msg = "Muito bom! Bom trabalho.";
        else if(score >= 10) msg = "Boa tentativa, continue estudando.";
        else msg = "Precisa revisar o conteúdo novamente.";

        document.getElementById('feedback-msg').innerText = msg;

        // Gera lista de revisão
        const reviewContainer = document.getElementById('review-container');
        reviewContainer.innerHTML = '';

        userAnswers.forEach((answer, idx) => {
            const isCorrect = answer.selectedOption === questions[answer.questionIndex].correct;
            const item = document.createElement('div');
            item.className = `review-item ${isCorrect ? 'correct' : 'wrong'}`;

            const qText = document.createElement('span');
            qText.className = 'review-q';
            qText.innerText = `Q${answer.questionIndex + 1}: ${answer.questionText.substring(0, 100)}...`;

            const ansText = document.createElement('div');
            ansText.className = 'review-ans';

            let statusClass = isCorrect ? 'text-green' : 'text-red';
            let statusText = isCorrect ? 'CORRETA' : 'ERRADA';

            ansText.innerHTML = `<strong>${statusText}</strong><br>Resposta correta: <span class="${statusClass}">${answersToLetter(questions[answer.questionIndex].correct)}</span>`;

            item.appendChild(qText);
            item.appendChild(ansText);
            reviewContainer.appendChild(item);
        });
    }

    function answersToLetter(index) {
        return String.fromCharCode(65 + index);
    }
</script>

